#include <stdio.h>
#include <stdlib.h>

long long fib(int n) {
    static long long f[45];
    f[0] = 0;
    if (n == 0) return f[0];
    f[1] = 1;
    for (int i = 2; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 2];
    }
    return f[n];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    printf("%lld\n", fib(n));
    return 0;
}

