int knapsack_max(int n, int weight[], int value[], int W) {
    static int dp[505];
    for (int w = 0; w <= W; w++) dp[w] = 0;
    for (int i = 0; i < n; i++) {
        for (int w = W; w >= weight[i]; w--) {
            if (dp[w - weight[i]] + value[i] > dp[w]) {
                dp[w] = dp[w - weight[i]] + value[i];
            }
        }
    }
    return dp[W];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int weight[55], value[55];
    for (int i = 0; i < n; i++) scanf("%d", &weight[i]);
    for (int i = 0; i < n; i++) scanf("%d", &value[i]);
    int W;
    scanf("%d", &W);
    printf("%d\n", knapsack_max(n, weight, value, W));
    return 0;
}

#include <stdio.h>
