int lcs_length(char a[], char b[]) {
    int n = 0, m = 0;
    while (a[n] != '\0') n++;
    while (b[m] != '\0') m++;
    static int dp[55][55];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            if (i == 0 || j == 0) {
                dp[i][j] = 0;
            } else if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
            }
        }
    }
    return dp[n][m];
}

int main(void) {
    char a[105], b[105];
    if (scanf("%s", a) != 1) return 0;
    scanf("%s", b);
    printf("%d\n", lcs_length(a, b));
    return 0;
}

