int subset_sum_exists(int n, int a[], int target) {
    static int dp[2001];
    for (int s = 0; s <= target; s++) dp[s] = 0;
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        for (int s = target; s >= a[i]; s--) {
            if (dp[s - a[i]]) dp[s] = 1;
        }
    }
    return dp[target];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int a[25];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int target;
    scanf("%d", &target);
    printf("%d\n", subset_sum_exists(n, a, target));
    return 0;
}

