long long rabbit_pairs(int months) {
    static long long memo[65];
    if (months <= 2) return 1;
    if (memo[months] != 0) return memo[months];
    memo[months] = rabbit_pairs(months - 1) + rabbit_pairs(months - 2);
    return memo[months];
}

int main(void) {
    int months;
    if (scanf("%d", &months) != 1) return 0;
    printf("%lld\n", rabbit_pairs(months));
    return 0;
}

