long long safe_routes(int n, int broken) {
    static long long ways[45];
    ways[0] = 1;
    for (int i = 1; i <= n; i++) {
        if (i == broken) {
            ways[i] = 0;
        } else {
            ways[i] = ways[i - 1];
            if (i >= 2) ways[i] += ways[i - 2];
        }
    }
    return ways[n];
}

int main(void) {
    int n, broken;
    if (scanf("%d %d", &n, &broken) != 2) return 0;
    printf("%lld\n", safe_routes(n, broken));
    return 0;
}

