int min_coins_dp(int n, int coins[], int amount) {
    static int dp[10003];
    dp[0] = 0;
    for (int s = 1; s <= amount; s++) dp[s] = amount + 1;
    for (int i = 0; i < n; i++) {
        for (int s = coins[i]; s <= amount; s++) {
            if (dp[s - coins[i]] + 1 < dp[s]) {
                dp[s] = dp[s - coins[i]] + 1;
            }
        }
    }
    return dp[amount] > amount ? -1 : dp[amount];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int coins[25];
    for (int i = 0; i < n; i++) scanf("%d", &coins[i]);
    int amount;
    scanf("%d", &amount);
    printf("%d\n", min_coins_dp(n, coins, amount));
    return 0;
}

