int max_loot(int val[], int n) {
    int prev2 = 0;
    int prev1 = 0;
    for (int i = 0; i < n; i++) {
        int best = prev1 > prev2 + val[i] ? prev1 : prev2 + val[i];
        prev2 = prev1;
        prev1 = best;
    }
    return prev1;
}

