int frog_min_cost(int n, int h[]) {
    static int dp[5005];
    dp[0] = 0;
    for (int i = 1; i < n; i++) {
        int c1 = dp[i - 1] + abs(h[i] - h[i - 1]);
        int c2 = (i >= 2) ? dp[i - 2] + abs(h[i] - h[i - 2]) : c1;
        dp[i] = c1 < c2 ? c1 : c2;
    }
    return dp[n - 1];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int h[5005];
    for (int i = 0; i < n; i++) scanf("%d", &h[i]);
    printf("%d\n", frog_min_cost(n, h));
    return 0;
}

