int min_paint_cost(int n, int cost[][3]) {
    int r = cost[0][0];
    int g = cost[0][1];
    int b = cost[0][2];
    for (int i = 1; i < n; i++) {
        int nr = cost[i][0] + (g < b ? g : b);
        int ng = cost[i][1] + (r < b ? r : b);
        int nb = cost[i][2] + (r < g ? r : g);
        r = nr;
        g = ng;
        b = nb;
    }
    int best = r < g ? (r < b ? r : b) : (g < b ? g : b);
    return best;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int cost[1000][3];
    for (int i = 0; i < n; i++) scanf("%d %d %d", &cost[i][0], &cost[i][1], &cost[i][2]);
    printf("%d\n", min_paint_cost(n, cost));
    return 0;
}

