long long grid_paths(int R, int C) {
    static long long dp[16][16];
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (i == 0 || j == 0) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
            }
        }
    }
    return dp[R - 1][C - 1];
}

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;
    printf("%lld\n", grid_paths(R, C));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXG 100

int min_path_sum(int R, int C, int g[][MAXG]) {
    static int dp[105][105];
    dp[0][0] = g[0][0];
    for (int j = 1; j < C; j++) dp[0][j] = dp[0][j - 1] + g[0][j];
    for (int i = 1; i < R; i++) dp[i][0] = dp[i - 1][0] + g[i][0];
    for (int i = 1; i < R; i++) {
        for (int j = 1; j < C; j++) {
            int up = dp[i - 1][j];
            int left = dp[i][j - 1];
            dp[i][j] = g[i][j] + (up < left ? up : left);
        }
    }
    return dp[R - 1][C - 1];
}

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;
    int g[MAXG][MAXG];
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++) scanf("%d", &g[i][j]);
    printf("%d\n", min_path_sum(R, C, g));
    return 0;
}

